function cardFor(p,tag){return `<a class="doc-card" href="${p.path}" data-route data-cat="${esc(tag??'')}"><span class="doc-card-visual" aria-hidden="true">${specimen[p.title]??''}</span><span class="doc-card-body"><span class="doc-card-meta">${esc(tag??hubOf(p)?.label??p.group)}${hasContract(p)?' · Stable':''}</span><strong>${esc(p.title)}</strong><span class="doc-card-text">${esc(guides[p.title]?.use??desc[p.title]??registry[p.title]?.purpose??pageDesc(p.title))}</span></span></a>`;}
function ratioBar(){return `<div class="ratio"><div class="ratio-bar" role="img" aria-label="${colorRatio.map(r=>`${r.role} ${r.share}%`).join(', ')}">${colorRatio.map(r=>`<i style="flex:${r.share};background:var(--hds-color-${r.swatch})"></i>`).join('')}</div><ul class="ratio-legend">${colorRatio.map(r=>`<li><span class="ratio-share">${r.share}<small>%</small></span><div class="ratio-info"><strong><i class="ratio-dot" aria-hidden="true" style="background:var(--hds-color-${r.swatch})"></i>${r.role}</strong><span>${r.use}</span><div class="ratio-tokens">${r.tokens.map(t=>`<code>${t}</code>`).join('')}</div></div></li>`).join('')}</ul></div>`;}
function overview(){const feed=['/components/button','/foundations/color','/components/textinput','/components/dialog','/components/alert','/components/table'].map(path=>pages.find(p=>p.path===path));
 return `<section class="hero"><p class="hero-eyebrow">Hudson Design System · Web 1.0</p><h1 id="pageTitle" tabindex="-1">웹을 만드는<br>하나의 기준.</h1><p class="hero-lead">토큰을 고르고, 검증된 컴포넌트를 조합하고, 같은 계약으로 AI에 넘기세요. 사람과 AI가 같은 언어로 Hudson의 화면을 만듭니다.</p><button class="hero-search" data-open-search><svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="6.5" stroke="currentColor" stroke-width="1.8"/><path d="m15 15 5 5" stroke="currentColor" stroke-width="1.8"/></svg><span>컴포넌트, 토큰, 상태 검색</span><kbd>/</kbd></button><div class="hero-actions"><a class="button primary lg" href="/components" data-route>컴포넌트 둘러보기</a><a class="button ghost lg" href="/ai-kit" data-route>AI Kit 열기 →</a></div></section>
 <section class="band"><div class="container"><div class="band-head"><p class="section-eyebrow" lang="en">Explore</p><h2>무엇을 찾고 있나요?</h2><p>대분류를 고르면 그 안의 문서를 카드로 볼 수 있어요.</p></div><div class="hub-grid">${hubs.filter(h=>!h.kit).map(h=>{const items=pages.filter(p=>p.group===h.group);return `<a class="hub-tile" href="${h.path}" data-route><span class="hub-tile-count">${items.length}개 문서</span><strong>${esc(h.label)}</strong><span>${esc(h.lead)}</span><span class="hub-tile-visual" aria-hidden="true">${specimen[items[0].title]??''}</span><span class="hub-tile-go" aria-hidden="true">→</span></a>`;}).join('')}</div></div></section>
 <section class="band dark"><div class="container"><p class="band-eyebrow">AI Kit</p><h2>AI가 새 값을<br>만들지 않게.</h2><p class="band-lead">ScreenBrief 하나와 컴포넌트 계약을 함께 넘기면, AI는 정해진 토큰과 컴포넌트 안에서만 화면을 조합해요.</p><ol class="steps">${[['목적','누가 무엇을 하려는 화면인지 ScreenBrief에 적어요.'],['선택','기존 패턴·컴포넌트·토큰에서만 골라요.'],['검수','상태·키보드·반응형 수용 기준으로 확인해요.']].map(([t,d])=>`<li><strong>${t}</strong><span>${d}</span></li>`).join('')}</ol><a class="button primary lg" href="/ai-kit" data-route>ScreenBrief 만들기</a></div></section>
 <section class="band"><div class="container"><div class="band-head"><p class="section-eyebrow" lang="en">Color ratio</p><h2>이 비율로 칠해요.</h2><p>화면 면적의 대부분은 밝은 바탕과 웜그레이가 맡고, 차콜이 구조를 잡고, 오렌지는 다음 행동에만 써요.</p></div>${ratioBar()}</div></section>
 <section class="band"><div class="container"><div class="band-head"><p class="section-eyebrow" lang="en">Popular</p><h2>자주 찾는 문서</h2></div><div class="feed">${feed.map(p=>`<a class="feed-item" href="${p.path}" data-route><span class="feed-meta">${esc(hubOf(p)?.label??p.group)} · Stable</span><strong>${esc(p.title)}</strong><span>${esc(guides[p.title]?.use??desc[p.title]??registry[p.title]?.purpose??pageDesc(p.title))}</span></a>`).join('')}</div></div></section>`;}
function hubPage(h){const items=pages.filter(p=>p.group===h.group);const tagOf=t=>h.cats?Object.entries(h.cats).find(([,list])=>list.includes(t))?.[0]:undefined;
 return `<section class="hub-hero container"><p class="hero-eyebrow">${esc(h.en)} · ${items.length}개 문서</p><h1 id="pageTitle" tabindex="-1">${esc(h.label)}</h1><p class="hero-lead">${esc(h.lead)}</p></section><div class="container">${h.cats?`<div class="filter" role="group" aria-label="${esc(h.label)} 분류"><button class="filter-chip" aria-pressed="true" data-filter="">전체 <span>${items.length}</span></button>${Object.entries(h.cats).map(([c,l])=>`<button class="filter-chip" aria-pressed="false" data-filter="${esc(c)}">${esc(c)} <span>${l.length}</span></button>`).join('')}</div>`:''}<div class="card-grid" id="hubCards">${items.map(p=>cardFor(p,tagOf(p.title))).join('')}</div><p class="sr-only" id="filterStatus" role="status" aria-live="polite"></p></div>`;}
const briefOptions={audience:['designer','developer','ai'],layout:['DocsShell','ProductShell','MediaWorkspace'],density:['comfortable','compact'],theme:['light','inverse'],dataSource:['static-registry','mock-api','product-api'],responsivePolicy:['docs-default','product-default'],requiredStates:['ready','loading','empty','filtered-empty','error','permission-denied','copy-success','copy-error'],acceptanceCriteria:['keyboard-complete','no-page-overflow','contrast-aa','zoom-200','zoom-400','reduced-motion','no-duplicate-action']};
const briefSchema={$schema:'https://json-schema.org/draft/2020-12/schema',title:'Hudson ScreenBrief',type:'object',additionalProperties:false,required:['schemaVersion','systemVersion','screenId','purpose','audience','primaryAction','secondaryActions','layout','density','theme','contentPriority','requiredStates','dataSource','responsivePolicy','acceptanceCriteria'],properties:{schemaVersion:{const:'1.0.0'},systemVersion:{const:'1.0.0'},screenId:{type:'string',minLength:1,pattern:'^[a-z0-9]+([.-][a-z0-9]+)*$'},purpose:{type:'string',minLength:1},audience:{type:'array',minItems:1,items:{enum:briefOptions.audience}},primaryAction:{type:'object',additionalProperties:false,required:['label','actionId'],properties:{label:{type:'string',minLength:1},actionId:{type:'string',minLength:1,pattern:'^[a-z0-9]+(-[a-z0-9]+)*$'}}},secondaryActions:{type:'array',items:{type:'string',minLength:1}},layout:{enum:briefOptions.layout},density:{enum:briefOptions.density},theme:{enum:briefOptions.theme},allowedComponents:{type:'array',items:{enum:Object.keys(registry)}},contentPriority:{type:'array',minItems:1,items:{type:'string',minLength:1}},requiredStates:{type:'array',minItems:1,items:{type:'string',minLength:1}},dataSource:{type:'string',minLength:1},responsivePolicy:{type:'string',minLength:1},acceptanceCriteria:{type:'array',minItems:1,items:{type:'string',minLength:1}}}};
const defaultBrief={schemaVersion:'1.0.0',systemVersion:'1.0.0',screenId:'product.project-create',purpose:'새 더빙 프로젝트의 이름과 번역 언어를 정하고 생성한다',audience:['designer','developer','ai'],primaryAction:{label:'프로젝트 생성',actionId:'create-project'},secondaryActions:['cancel'],layout:'ProductShell',density:'comfortable',theme:'light',allowedComponents:['Button','Field','TextInput','Combobox','Alert'],contentPriority:['purpose','form','primary-action'],requiredStates:['ready','loading','error'],dataSource:'mock-api',responsivePolicy:'product-default',acceptanceCriteria:['keyboard-complete','no-page-overflow','contrast-aa','no-duplicate-action']};
function validateSchema(schema,value,path='$'){const e=[],t=Array.isArray(value)?'array':value===null?'null':typeof value;
 if('const' in schema&&value!==schema.const)e.push(`${path}: ${JSON.stringify(schema.const)}이어야 해요.`);
 if(schema.enum&&!schema.enum.includes(value))e.push(`${path}: ${schema.enum.join(', ')} 중 하나여야 해요.`);
 if(schema.type&&schema.type!==t)return [...e,`${path}: ${schema.type} 형식이어야 해요.`];
 if(t==='string'){if(schema.minLength&&value.trim().length<schema.minLength)e.push(`${path}: 비어 있어요.`);if(schema.pattern&&value&&!new RegExp(schema.pattern).test(value))e.push(`${path}: 소문자·숫자·하이픈 형식이어야 해요.`);}
 if(t==='array'){if(schema.minItems&&value.length<schema.minItems)e.push(`${path}: 하나 이상 선택하세요.`);if(schema.items)value.forEach((v,i)=>e.push(...validateSchema(schema.items,v,`${path}[${i}]`)));}
 if(t==='object'&&(schema.properties||schema.required)){for(const k of schema.required??[])if(!(k in value))e.push(`${path}.${k}: 필수 항목이에요.`);for(const [k,v]of Object.entries(value)){if(schema.properties?.[k])e.push(...validateSchema(schema.properties[k],v,`${path}.${k}`));else if(schema.additionalProperties===false)e.push(`${path}.${k}: 정의되지 않은 항목이에요.`);}}
 return e;}
function aiKit(){const b=defaultBrief,opt=(name,vals,cur)=>`<select class="input" id="brief-${name}" name="${name}">${vals.map(v=>`<option ${v===cur?'selected':''}>${v}</option>`).join('')}</select>`,checks=(name,vals,cur)=>`<div class="check-grid">${vals.map(v=>`<label><input type="checkbox" name="${name}" value="${esc(v)}" ${cur.includes(v)?'checked':''}> ${esc(v)}</label>`).join('')}</div>`;
 return section('download','AI에 전달할 자료',`<p class="section-lead">아래 네 파일과 ScreenBrief 하나면 AI가 새 값을 만들지 않고 화면을 조합할 수 있어요.</p><div class="file-grid">${[['/assets/Hudson_AI_Web_Design_System_Spec.md','전체 명세','설계 이유·규칙·수용 기준 (Markdown)'],['/tokens.json','Tokens','색·타이포·간격·곡률·그림자 원본'],['/registry.json','Component registry','20개 컴포넌트 계약·코드·토큰 바인딩'],['/screen-brief.schema.json','ScreenBrief Schema','화면 요청서 JSON Schema']].map(([href,t,d])=>`<a class="file-card" href="${href}" download><strong>${t} <span aria-hidden="true">↓</span></strong><span>${d}</span></a>`).join('')}</div>`)+
 callout('AI에게는 기준을 먼저 전달하세요.','목적 → 패턴 → 컴포넌트 → 토큰 → 상태 → 검수 순서로 실행해요. 임의 HEX·간격·radius·새 컴포넌트를 만들지 않아요.')+
 section('refs','패턴과 가이드',`<p class="section-lead">AI에 넘길 화면 단위와 작성 기준이에요. 위임 프롬프트에는 이 문서의 계약이 함께 담겨요.</p><div class="hub-grid">${hubs.filter(h=>h.kit).map(h=>{const items=pages.filter(p=>p.group===h.group);return `<a class="hub-tile" href="${h.path}" data-route><span class="hub-tile-count">${items.length}개 문서</span><strong>${esc(h.label)}</strong><span>${esc(h.lead)}</span><span class="hub-tile-visual" aria-hidden="true">${specimen[items[0].title]??''}</span><span class="hub-tile-go" aria-hidden="true">→</span></a>`;}).join('')}</div>`)+
 section('brief','ScreenBrief 만들기',`<div class="brief-layout"><form id="briefForm" class="demo-stack" novalidate>
 <fieldset class="brief-group"><legend>무엇을 만드나요?</legend><div class="field"><label for="brief-screenId">화면 ID</label><input class="input" id="brief-screenId" name="screenId" value="${esc(b.screenId)}" aria-describedby="brief-screenId-help"><span class="field-help" id="brief-screenId-help">소문자·숫자·점·하이픈. 예: product.project-create</span></div><div class="field"><label for="brief-purpose">화면의 목적</label><textarea class="input" id="brief-purpose" name="purpose" rows="2">${esc(b.purpose)}</textarea></div><div class="field"><span class="field-label">대상</span>${checks('audience',briefOptions.audience,b.audience)}</div></fieldset>
 <fieldset class="brief-group"><legend>가장 중요한 행동</legend><div class="field-row"><div class="field"><label for="brief-actionLabel">버튼 문구</label><input class="input" id="brief-actionLabel" name="actionLabel" value="${esc(b.primaryAction.label)}"></div><div class="field"><label for="brief-actionId">actionId</label><input class="input" id="brief-actionId" name="actionId" value="${esc(b.primaryAction.actionId)}"></div></div><div class="field"><label for="brief-secondary">보조 행동 <span class="optional">쉼표로 구분</span></label><input class="input" id="brief-secondary" name="secondary" value="${esc(b.secondaryActions.join(', '))}"></div></fieldset>
 <fieldset class="brief-group"><legend>구조와 컴포넌트</legend><div class="field-row"><div class="field"><label for="brief-layout">레이아웃</label>${opt('layout',briefOptions.layout,b.layout)}</div><div class="field"><label for="brief-density">밀도</label>${opt('density',briefOptions.density,b.density)}</div><div class="field"><label for="brief-theme">테마</label>${opt('theme',briefOptions.theme,b.theme)}</div></div><div class="field"><span class="field-label">사용할 컴포넌트</span>${checks('allowedComponents',Object.keys(registry),b.allowedComponents)}</div><div class="field"><label for="brief-priority">콘텐츠 우선순위 <span class="optional">쉼표로 구분</span></label><input class="input" id="brief-priority" name="priority" value="${esc(b.contentPriority.join(', '))}"></div></fieldset>
 <fieldset class="brief-group"><legend>상태와 검수</legend><div class="field"><span class="field-label">필요한 상태</span>${checks('requiredStates',briefOptions.requiredStates,b.requiredStates)}</div><div class="field-row"><div class="field"><label for="brief-dataSource">데이터</label>${opt('dataSource',briefOptions.dataSource,b.dataSource)}</div><div class="field"><label for="brief-responsive">반응형 정책</label>${opt('responsivePolicy',briefOptions.responsivePolicy,b.responsivePolicy)}</div></div><div class="field"><span class="field-label">수용 기준</span>${checks('acceptanceCriteria',briefOptions.acceptanceCriteria,b.acceptanceCriteria)}</div></fieldset>
 </form><div class="brief-output"><div id="briefValidity" role="status" aria-live="polite"></div><div class="button-row"><button class="button primary" type="button" id="briefCopyPackage">${copyIcon} 위임 패키지 복사</button><button class="button secondary" type="button" id="briefCopy">JSON 복사</button><button class="button secondary" type="button" id="briefDownload">JSON 다운로드 ↓</button></div><p class="field-help">위임 패키지 = 구현 지시문 + ScreenBrief + 선택한 컴포넌트의 계약. 한 번에 붙여 넣으면 돼요.</p><div id="briefOutput"></div></div></div>`)+
 section('prompt','구현 위임 프롬프트',codePanel(basePrompt,'ai-instruction.txt'))+section('validation','수용 기준',specExcerpt('검수'))+specDetails('AI Kit');}
const basePrompt='Hudson Design System v1.0을 기준으로 화면을 구현하세요.\n먼저 저장소 구조와 AGENTS.md, 의존성을 확인하고 기존 스택을 유지하세요.\nScreenBrief의 목적·사용자·주요 행동을 기준으로 기존 Pattern을 선택하세요.\nallowedComponents와 semantic token(--hds-*)에서만 선택하고 HEX·임의 간격·새 컴포넌트를 만들지 마세요.\n각 컴포넌트 계약의 props·states·keyboardBehavior·tokenBindings를 구현하세요.\nrequiredStates를 모두 화면에 구현하고 데모 데이터는 데모라고 표시하세요.\n알럿·토스트·다이얼로그에 아이콘을 넣지 말고, Pagination 이전·다음은 테두리 없는 텍스트 액션으로, 토스트·툴팁은 오렌지 포인트 면과 차콜 글자로 구현하세요.\n언어 전환 라벨은 모든 화면에서 KO·EN으로 통일하세요.\nacceptanceCriteria를 검사하고 변경 파일·검증 결과·미해결 항목을 보고하세요.';
function markdown(raw){
 let blocks=[];raw=raw.replace(/```([^\n]*)\n([\s\S]*?)```/g,(_,lang,body)=>{blocks.push(codePanel(body.trim(),lang||'code'));return `\n@@BLOCK${blocks.length-1}@@\n`;});
 const inline=t=>esc(t).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code class="inline">$1</code>').replace(/https:\/\/[^\s<]+/g,u=>`<a class="text-link" href="${u}" target="_blank" rel="noopener">${u}</a>`);
 const lines=raw.split('\n');let out='',list=false;
 for(let i=0;i<lines.length;i++){const l=lines[i];if(!l.trim()){if(list){out+='</ul>';list=false;}continue;}if(l.startsWith('|')&&lines[i+1]?.match(/^\|[- :|]+\|$/)){if(list){out+='</ul>';list=false;}const split=t=>t.trim().slice(1,-1).split('|').map(x=>inline(x.trim()));const h=split(l),rows=[];i+=2;while(lines[i]?.startsWith('|')){rows.push(split(lines[i]));i++;}i--;out+=table(h,rows);continue;}if(l.match(/^@@BLOCK\d+@@$/)){out+=blocks[+l.match(/\d+/)[0]];continue;}if(l.startsWith('### ')){out+=`<h3>${inline(l.slice(4))}</h3>`;continue;}if(l.startsWith('> ')){out+=`<blockquote>${inline(l.slice(2))}</blockquote>`;continue;}if(l.match(/^(- |\d+\. )/)){if(!list){out+='<ul>';list=true;}out+=`<li>${inline(l.replace(/^(- |\d+\. )/,''))}</li>`;continue;}if(list){out+='</ul>';list=false;}out+=`<p>${inline(l)}</p>`;}if(list)out+='</ul>';return out;
}
function specExcerpt(title){let idx=title==='Typography'?6:['Color'].includes(title)?5:['Spacing','Radius','Elevation','Layout'].includes(title)?7:['Motion','Iconography'].includes(title)?10:['Upload','AsyncJob','MediaWorkspace','LiveSession','EmptyState','ErrorRecovery'].includes(title)?9:title==='AI Kit'?13:title==='검수'?15:4;const s=specSections.find(x=>x.title.startsWith(idx+'.'));return s?`<div class="spec-section">${markdown(s.body)}</div>`:'<p>명세를 불러오지 못했어요. <a class="text-link" href="/assets/Hudson_AI_Web_Design_System_Spec.md" download>원본 파일 내려받기</a></p>';}
function specDetails(t){return section('full-spec','상세 명세',`<details class="json-details"><summary>원본 명세 해당 절 펼치기</summary>${specExcerpt(t)}</details>`);}
function specification(){return `<div class="button-row"><a class="button primary" href="/assets/Hudson_AI_Web_Design_System_Spec.md" download>원본 명세 다운로드 ↓</a></div>`+specSections.map((s,i)=>section('spec-'+i,esc(s.title),`<div class="spec-section">${markdown(s.body)}</div>`)).join('');}
function guide(p){if(p.title==='Getting Started')return section('steps','세 단계로 시작하기',rules([['01 · 목적을 정의하세요.','사용자, 가장 중요한 정보, 다음 행동, 필요한 상태를 ScreenBrief에 기록합니다.'],['02 · 기준을 선택하세요.','기존 Pattern·Component·semantic token을 선택해 화면을 조합합니다.'],['03 · 실제로 검수하세요.','키보드, 반응형, 확대, 실패, 긴 텍스트를 확인합니다.'],['04 · 변경을 기록하세요.','새 규칙이 필요하면 이유·영향·예제와 함께 시스템에 반영합니다.']]))+section('technical','실행 구조',codePanel('dist/\n  index.html         문서 Shell\n  app.js             Registry 기반 라우팅·예제\n  style.css          Semantic token 기반 스타일\n  tokens.json        토큰 데이터\n  registry.json      컴포넌트 계약\n  spec.json          원본 명세 전체\n  screen-brief.schema.json\n  assets/            폰트·라이선스·원본 명세','project.structure'))+section('related','다음 단계',related(['/foundations/typography','/components/button','/ai-kit']));
 if(p.title==='Design Principles')return section('laws','UX 원칙을 화면의 기준으로',rules([['Hick · 선택을 구조화','핵심 행동을 먼저 보여주고 고급 옵션은 접습니다. 긴 목록에는 검색을 제공합니다.'],['Fitts · 쉽게 누르게','중요 행동은 충분한 크기와 맥락 가까운 위치를 확보합니다.'],['Jakob · 익숙한 웹 관습','링크는 이동, 버튼은 실행. Cmd/Ctrl+K, Esc 등 익숙한 조작을 따릅니다.'],['Proximity · 관계를 보여주기','라벨·입력·설명·오류는 가깝게, 다른 그룹은 여백으로 구분합니다.'],['Von Restorff · 하나를 강조','작업 맥락당 주요 행동을 하나로 정하고 오렌지를 남용하지 않습니다.'],['AI · 선택하고 조합하기','AI가 값을 새로 발명하기보다 역할과 상태가 정해진 시스템에서 선택하게 합니다.']]))+section('detail','실행 기준',specExcerpt('principles'));
 if(p.title==='Changelog')return section('unreleased','Unreleased · UX 개선',checklist(['타이포·컬러 정리: 제목 크기(heading-xl 3rem·lg 2.25rem)와 섹션 여백 확대, 섹션 영문 라벨, 오렌지 램프 50–900 재설계(어두운 단계는 웜그레이 쪽 색상각), action.primary.hover/pressed 추가','색 규칙: 배지·알럿·토스트·툴팁·다이얼로그를 오렌지·차콜·웜그레이·화이트 팔레트만으로 재구성하고 초록·노랑·빨강 제거, 상태 의미는 아이콘·글자·차콜 채움으로 구분 (--hds-status-*-border 추가)','입력 필드: 연한 웜그레이 바탕(field.bg)과 연한 경계(field.border·hover) 적용, 경계 대비 3:1 미만은 요청에 따른 의도된 절충 (placeholder·글자는 4.5:1 유지)','다크 모드: 헤더 토글·시스템 설정·?theme=dark, 시맨틱 토큰 다크 값(bg.inverse·text.inverse·action.primary.pressed.fg·warm-800 추가), 라이트·다크 모두 대비 4.5:1 빌드 검사','English 버전: 헤더 KO/EN 토글·?lang=en, 화면 문구·복사되는 위임 프롬프트·계약 JSON·전체 명세(spec.en.json)를 영어로 제공, 선택은 브라우저에 저장','제목을 Hudson Design System으로 통일(브랜드·문서 제목·푸터·위임 프롬프트), 브랜드 워드마크는 한 굵기·한 색으로, 컬러 비율 범례를 모바일에서 행 목록(비율·역할·토큰 칩)으로 재배치','Pagination은 텍스트 액션으로, 언어 토글 라벨은 KO·EN으로 통일, 카드 제목 행간·h3 자간 보정, AI 전달 명세·위임 프롬프트에 반영','미니멀 정리: 알럿·토스트·다이얼로그 아이콘 제거, 알럿은 옅은 바탕+왼쪽 표시선, 배지는 옅은 톤, 토스트·툴팁은 오렌지 포인트 면(차콜 글자), 다이얼로그 배경 딤 완화','디자인 개편: 사이드바·우측 목차 제거, 상단 대분류 5개 + 허브 페이지 본문 카드, sticky 로컬 내비, 팔레트 사용 비율(60·25·12·3) 적용','검색: 토큰·속성·상태·명세 절까지 색인, Enter로 이동, Esc 한 번에 닫기, / 단축키, 닫으면 초점 복귀','컴포넌트 20개에 사용·회피 기준, 대안, 키보드, 상태별 토큰 바인딩, 실사용 코드 추가 (registry.json 포함)','모든 파운데이션·컴포넌트·패턴 페이지에 AI 위임 프롬프트 복사 추가, 중복 섹션 제거','ScreenBrief 빌더: 모든 스키마 필드 입력, 실시간 스키마 검증, 위임 패키지 복사','screen-brief.schema.json: 선택 항목 allowedComponents 추가, screenId·actionId 형식 검증 (호환 추가)','tokens.css: --hds-status-* 상태색 추가, 사이트 CSS의 HEX 제거, 명세 §12 spacing 이름을 px 기준으로 통일','빌드 검사: 계약 중복·알 수 없는 토큰·데모 마크업·스키마 불일치·CSS HEX를 실패로 처리']))+section('version','v1.0.0 · 2026. 10. 10.',checklist(['Hudson 브랜드 컬러와 웹 Typography 역할 토큰 정의','반응형 DocsShell, 검색·목차·직접 진입·404 구현','20개 컴포넌트의 상태·API·계약과 인터랙션 예제','8개 Hudson 패턴과 데모 상태 전이','AI Kit, ScreenBrief Schema, 원본 명세 다운로드']))+section('policy','변경과 예외 관리',`<div class="spec-section">${markdown(specSections.find(x=>x.title.startsWith('14.'))?.body??'')}</div>`);
 return section('guidelines','접근성·문장·국제화 기준',specExcerpt('Motion'))+section('checks','검수 기준',specExcerpt('검수'));
}
function body(p){if(p.title==='Typography')return typography();if(p.group==='파운데이션')return foundation(p);if(registry[p.title])return component(p);if(p.group==='작업 패턴')return pattern(p);if(p.title==='Overview')return overview();if(p.title==='AI Kit')return aiKit();if(p.title==='Specification')return specification();return guide(p);}
function footer(p){const list=pages.filter(x=>x.group===p.group),i=list.findIndex(x=>x.path===p.path),prev=list[i-1],next=list[i+1],hub=hubOf(p);if(!prev&&!next&&!hub)return '';return `<nav class="page-footer" aria-label="이전·다음 문서">${prev?`<a href="${prev.path}" data-route><small>이전</small>← ${esc(prev.title)}</a>`:hub?`<a href="${hub.path}" data-route><small>목록</small>← ${esc(hub.label)} 전체</a>`:'<span></span>'}${next?`<a class="next" href="${next.path}" data-route><small>다음</small>${esc(next.title)} →</a>`:hub?`<a class="next" href="${hub.path}" data-route><small>목록</small>${esc(hub.label)} 전체 →</a>`:''}</nav>`;}
function siteFooterHTML(){return `<div class="container"><div class="sitemap">${[...hubs.filter(h=>!h.kit).map(h=>[h.label,h.path,pages.filter(p=>p.group===h.group)]),['AI Kit','/ai-kit',pages.filter(p=>hubs.some(h=>h.kit&&h.group===p.group)&&['Getting Started','Specification','Changelog','Upload','AsyncJob','MediaWorkspace'].includes(p.title))]].map(([label,path,items])=>`<div><a class="sitemap-head" href="${path}" data-route>${esc(label)}</a>${items.map(p=>`<a href="${p.path}" data-route>${esc(p.title)}</a>`).join('')}</div>`).join('')}</div><p class="footer-legal">Hudson Design System · Web v1.0.0 · 데모 예제는 실제 서비스에 연결되지 않아요.</p></div>`;}
function render(path,focus=false){path=path.replace(/\/$/,'')||'/overview';clearTimeout(jobTimer);clearInterval(mediaTimer);currentHub=hubs.find(h=>h.path===path)??null;currentPage=currentHub?null:pages.find(x=>x.path===path);
 $('#gnav').innerHTML=topNavHTML();$('#mobileNav').innerHTML=navHTML();$('#siteFooter').innerHTML=siteFooterHTML();$('#localNav').hidden=true;$('#localNav').innerHTML='';observer?.disconnect();
 if(currentHub){document.title=currentHub.label+' — Hudson Design System';main.className='is-hub';main.innerHTML=hubPage(currentHub);bindHub();}
 else if(!currentPage){main.className='';main.innerHTML='<div class="container"><header class="page-head"><h1 id="pageTitle" tabindex="-1">문서를 찾을 수 없어요.</h1><p class="page-description">주소를 확인하거나 검색으로 필요한 기준을 찾아보세요.</p></header><div class="button-row"><button class="button primary" data-open-search>문서 검색</button><a class="button secondary" href="/overview" data-route>처음으로</a></div></div>';}
 else if(currentPage.title==='Overview'){document.title='Hudson Design System';main.className='is-home';main.innerHTML=overview();}
 else{document.title=currentPage.title+' — Hudson Design System';main.className='is-doc';main.innerHTML=`<div class="container">${header(currentPage)+body(currentPage)+footer(currentPage)}</div>`;
  const sections=$$('main .container > .section');if(sections.length>1){$('#localNav').innerHTML=`<div class="container local-inner"><a class="local-title" href="#pageTitle">${esc(currentPage.title)}</a><nav class="local-links" aria-label="이 페이지 목차">${sections.map(s=>`<a href="#${s.id}">${esc(s.querySelector('h2').textContent)}</a>`).join('')}</nav>${hasContract(currentPage)?`<button class="button secondary sm local-cta" data-copy-prompt>위임 프롬프트</button>`:''}</div>`;$('#localNav').hidden=false;
   observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('#localNav .local-links a').forEach(a=>{const on=a.hash==='#'+e.target.id;a.classList.toggle('active',on);if(on){a.setAttribute('aria-current','location');const box=a.parentElement,l=a.offsetLeft-box.offsetLeft;if(l<box.scrollLeft||l+a.offsetWidth>box.scrollLeft+box.clientWidth)box.scrollLeft=Math.max(0,l-16);}else a.removeAttribute('aria-current');});}},{rootMargin:`-${Math.round($('.header').offsetHeight+$('#localNav').offsetHeight)+24}px 0px -55% 0px`});sections.forEach(s=>observer.observe(s));}
  bindPage();}
 if(focus){$('#pageTitle')?.focus({preventScroll:true});window.scrollTo(0,0);}}
let currentHub=null,observer;
function bindHub(){const chips=$$('.filter-chip'),cards=$$('#hubCards .doc-card');chips.forEach(c=>c.onclick=()=>{const f=c.dataset.filter;chips.forEach(x=>x.setAttribute('aria-pressed',String(x===c)));let n=0;cards.forEach(card=>{const show=!f||card.dataset.cat===f;card.hidden=!show;if(show)n++;});$('#filterStatus').textContent=`${f||'전체'} ${n}개`;});}
function navigate(href){const [path,hash]=href.split('#');const same=currentPage&&path===currentPage.path;history.pushState({},'',href);if(!same)render(path,!hash);if($('#navDialog').open)$('#navDialog').close();if(hash)requestAnimationFrame(()=>{const el=document.getElementById(hash);if(!el)return;el.scrollIntoView();const h=el.querySelector('h2')??el;h.setAttribute('tabindex','-1');h.focus({preventScroll:true});});}
document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();if($('#searchDialog').open){pendingRouteFocus=true;$('#searchDialog').close();}navigate(a.getAttribute('href'));}});
window.addEventListener('popstate',()=>{render(location.pathname,!location.hash);if(location.hash)$(location.hash)?.scrollIntoView();});
