 if($('#tooltipTrigger')){const show=()=>$('#tooltipText').classList.add('visible'),hide=()=>$('#tooltipText').classList.remove('visible');on('#tooltipTrigger','pointerenter',show);on('#tooltipTrigger','focus',show);on('#tooltipTrigger','pointerleave',hide);on('#tooltipTrigger','blur',hide);on('#tooltipTrigger','keydown',e=>{if(e.key==='Escape')hide();});}
