function bindDemoTabs(){const tabs=$$('.demo-tab');const pick=t=>tabs.forEach(x=>{const v=x===t;x.setAttribute('aria-selected',String(v));x.tabIndex=v?0:-1;$('#'+x.getAttribute('aria-controls')).hidden=!v;});tabs.forEach((t,i)=>{t.onclick=()=>pick(t);t.onkeydown=e=>{const k={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(k===undefined)return;e.preventDefault();const n=tabs[(k+tabs.length)%tabs.length];pick(n);n.focus();};});}
function activateTab(id){$$('.preview-toolbar .tab').forEach(t=>{const v=t.dataset.tab===id;t.setAttribute('aria-selected',String(v));t.tabIndex=v?0:-1;$('#panel-'+t.dataset.tab).hidden=!v;});}
function bindCombo(){const input=$('#languageCombo'),list=$('#languageOptions');const langs=['한국어','English','日本語','Español','Français','Deutsch','中文','Português'];let filtered=[],idx=-1;
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');};const choose=v=>{input.value=v;$('#comboStatus').textContent=v+' 선택됨';close();};const show=()=>{filtered=langs.filter(v=>v.toLowerCase().includes(input.value.toLowerCase()));idx=-1;list.hidden=false;input.setAttribute('aria-expanded','true');list.innerHTML=filtered.length?filtered.map((v,i)=>`<div class="nav-link" role="option" id="lang-${i}" aria-selected="false">${esc(v)}</div>`).join(''):'<p class="field-help">검색 결과가 없어요.</p>';list.querySelectorAll('[role=option]').forEach((el,i)=>{el.onpointerdown=e=>{e.preventDefault();choose(filtered[i]);};});};input.oninput=show;input.onfocus=show;input.onblur=close;input.onkeydown=e=>{if(e.key==='Escape'){close();return;}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(list.hidden)show();if(!filtered.length)return;idx=Math.max(0,Math.min(filtered.length-1,idx+(e.key==='ArrowDown'?1:-1)));list.querySelectorAll('[role=option]').forEach((el,i)=>{el.setAttribute('aria-selected',String(i===idx));el.classList.toggle('active',i===idx);});input.setAttribute('aria-activedescendant','lang-'+idx);}if(e.key==='Enter'&&idx>=0&&!list.hidden){e.preventDefault();choose(filtered[idx]);}};
}
function bindTable(){const data=[{name:'Hudson 브랜드 필름',lang:'English',state:'완료'},{name:'글로벌 컨퍼런스',lang:'한국어',state:'검토 필요'},{name:'제품 소개 영상',lang:'日本語',state:'대기'}];let asc=false;const selected=new Set();let visible=[];const update=()=>{const q=$('#tableFilter').value.toLowerCase();visible=data.filter(r=>r.name.toLowerCase().includes(q));if(asc)visible.sort((a,b)=>a.name.localeCompare(b.name,'ko'));$('#demoRows').innerHTML=visible.length?visible.map(r=>`<tr><td><input type="checkbox" aria-label="${esc(r.name)} 선택" data-name="${esc(r.name)}" ${selected.has(r.name)?'checked':''}></td><td>${esc(r.name)}</td><td>${r.lang}</td><td><span class="badge ${r.state==='완료'?'success':r.state==='검토 필요'?'warning':''}">${r.state}</span></td></tr>`).join(''):'<tr><td colspan="4">검색 결과가 없어요. 다른 키워드를 입력하세요.</td></tr>';const all=$('#selectAll');all.checked=visible.length>0&&visible.every(r=>selected.has(r.name));all.indeterminate=visible.some(r=>selected.has(r.name))&&!all.checked;$('#tableStatus').textContent=`데모 데이터 · ${visible.length}개 표시 · ${selected.size}개 선택`;$$('#demoRows input').forEach(i=>i.onchange=()=>{if(i.checked)selected.add(i.dataset.name);else selected.delete(i.dataset.name);update();});};on('#tableFilter','input',update);on('#sortTable','click',()=>{asc=!asc;$('#sortHeader').setAttribute('aria-sort',asc?'ascending':'none');update();});on('#selectAll','change',e=>{visible.forEach(r=>{if(e.target.checked)selected.add(r.name);else selected.delete(r.name);});update();});update();}
function bindUpload(){const output=$('#fileResults'),zone=$('#dropzone');const show=files=>{output.replaceChildren();if(!files.length){output.textContent='선택된 파일이 없어요.';return;}for(const file of files){const el=document.createElement('div');el.textContent=file.name+' · '+(file.size/1024/1024).toFixed(2)+'MB · 전송되지 않음';output.append(el);}};on('#fileInput','change',e=>show(e.target.files));on('#fileLabel','keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('#fileInput').click();}});zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');show(e.dataTransfer.files);};}
function bindJob(){let state='queued';const set=(s,label)=>{state=s;$('#jobState').textContent=s;$('#jobStage').textContent=label;$('#jobStart').disabled=['running','canceling'].includes(s);$('#jobCancel').disabled=s!=='running';if(s==='running')$('#jobProgress').removeAttribute('value');else $('#jobProgress').value=s==='succeeded'?100:0;};on('#jobStart','click',()=>{clearTimeout(jobTimer);set('running','번역 중 · 데모');jobTimer=setTimeout(()=>{set('succeeded','데모 작업 완료');notify('상태 전이 시연 완료 · 실제 처리 없음');},3000);});on('#jobCancel','click',()=>{clearTimeout(jobTimer);set('canceling','취소 요청 처리 중');jobTimer=setTimeout(()=>set('canceled','데모 작업 취소됨'),400);});on('#jobFail','click',()=>{clearTimeout(jobTimer);set('failed','데모 처리 실패 · 다시 실행할 수 있어요.');});}
function bindMedia(){let playing=false;const seek=$('#mediaSeek'),play=$('#mediaPlay');const sync=()=>$('#mediaTime').textContent='00:'+String(seek.value).padStart(2,'0');on('#mediaSeek','input',sync);play.onclick=()=>{playing=!playing;play.textContent=playing?'Ⅱ 일시정지':'▶ 재생';play.setAttribute('aria-label',playing?'타임라인 데모 일시정지':'타임라인 데모 재생');clearInterval(mediaTimer);if(playing)mediaTimer=setInterval(()=>{seek.value=+seek.value>=24?0:+seek.value+1;sync();},1000);};}
function bindLive(){on('#liveDisconnect','click',()=>{$('#liveBadge').className='badge danger';$('#liveBadge').textContent='× 연결 끊김';$('#liveReconnect').hidden=false;$('#liveDisconnect').disabled=true;$('#liveStatus').textContent='데모 연결이 끊겼어요. 실제 송출에는 영향이 없습니다.';});on('#liveReconnect','click',()=>{$('#liveBadge').className='badge warning';$('#liveBadge').textContent='↻ 재연결 중';$('#liveReconnect').disabled=true;jobTimer=setTimeout(()=>{$('#liveBadge').className='badge success';$('#liveBadge').textContent='● 연결됨';$('#liveReconnect').hidden=true;$('#liveReconnect').disabled=false;$('#liveDisconnect').disabled=false;$('#liveStatus').textContent='데모 연결 복구 · '+new Intl.DateTimeFormat('ko-KR',{timeStyle:'medium',timeZone:'Asia/Seoul'}).format(new Date())+' KST';},1200);});}
function bindBrief(){const f=$('#briefForm'),list=v=>v.split(',').map(x=>x.trim()).filter(Boolean),checked=n=>$$(`#briefForm input[name=${n}]:checked`).map(i=>i.value);
 const create=()=>({schemaVersion:'1.0.0',systemVersion:'1.0.0',screenId:f.screenId.value.trim(),purpose:f.purpose.value.trim(),audience:checked('audience'),primaryAction:{label:f.actionLabel.value.trim(),actionId:f.actionId.value.trim()},secondaryActions:list(f.secondary.value),layout:f.layout.value,density:f.density.value,theme:f.theme.value,allowedComponents:checked('allowedComponents'),contentPriority:list(f.priority.value),requiredStates:checked('requiredStates'),dataSource:f.dataSource.value,responsivePolicy:f.responsivePolicy.value,acceptanceCriteria:checked('acceptanceCriteria')});
 let current=create(),errors=[];const update=()=>{current=create();errors=validateSchema(briefSchema,current);$('#briefValidity').innerHTML=errors.length?`<div class="validity bad"><strong>${errors.length}개 항목을 확인하세요.</strong><ul>${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'<div class="validity ok"><strong>✓ 스키마 검증 통과</strong> screen-brief.schema.json 기준</div>';$('#briefOutput').innerHTML=codePanel(JSON.stringify(current,null,2),'screen-brief.json');['briefCopyPackage','briefCopy','briefDownload'].forEach(id=>$('#'+id).setAttribute('aria-disabled',String(!!errors.length)));};
 const guard=fn=>()=>{if(errors.length){notify('먼저 검증 오류를 고쳐 주세요.');$('#briefValidity').scrollIntoView({block:'nearest'});return;}fn();};
 f.addEventListener('input',update);f.addEventListener('change',update);
 on('#briefCopy','click',guard(()=>copy(JSON.stringify(current,null,2),'ScreenBrief JSON을 복사했어요.')));on('#briefDownload','click',guard(()=>download(current.screenId+'.screen-brief.json',current)));
 on('#briefCopyPackage','click',guard(()=>{const comps=current.allowedComponents.map(id=>contract(pages.find(p=>p.title===id)));copy([basePrompt,'','## ScreenBrief',JSON.stringify(current,null,2),'','## 사용할 컴포넌트 계약',JSON.stringify(comps,null,2),'','토큰: '+location.origin+'/tokens.css'].join('\n'),'위임 패키지를 복사했어요. AI에 그대로 붙여 넣으세요.');}));
 update();}
try{const r=await fetch('/spec.json');if(!r.ok)throw Error('명세 로딩 실패');specSections=await r.json();}catch{notify('명세 본문을 불러오지 못했어요. 원본 다운로드를 이용하세요.');}
/* ===== 환경설정: 언어 · 테마 (브라우저 전용) ===== */
const rootEl=document.documentElement;
LANG=rootEl.lang==='en'?'en':'ko';
const sunIcon='<svg class="i-sun" width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="4" stroke="currentColor" stroke-width="1.8"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6l1.4 1.4M17 17l1.4 1.4M18.4 5.6L17 7M7 17l-1.4 1.4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',moonIcon='<svg class="i-moon" width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>';
function prefsHTML(){const dark=rootEl.dataset.theme==='dark';return `<div class="seg" role="group" aria-label="언어 / Language"><button type="button" data-lang="ko" aria-pressed="${LANG==='ko'}" aria-label="한국어" lang="ko">KO</button><button type="button" data-lang="en" aria-pressed="${LANG==='en'}" aria-label="English" lang="en">EN</button></div><button type="button" class="icon-button theme-toggle" data-theme-toggle aria-label="${dark?'라이트 모드로 전환':'다크 모드로 전환'}">${sunIcon}${moonIcon}</button>`;}
function renderPrefs(){$$('[data-prefs]').forEach(el=>{el.innerHTML=prefsHTML();});localizeNode(document.body);}
function setTheme(t,save=true){rootEl.dataset.theme=t;if(save)try{localStorage.setItem('hds-theme',t);}catch{}document.querySelector('meta[name=theme-color]')?.setAttribute('content',t==='dark'?'#171614':'#FAF9F6');renderPrefs();}
async function setLang(l,save=true){if(l==='en'&&!EN)await loadDict();LANG=l;rootEl.lang=l;await loadSpec();if(save)try{localStorage.setItem('hds-lang',l);}catch{}try{const u=new URL(location.href);if(l==='en')u.searchParams.set('lang','en');else u.searchParams.delete('lang');history.replaceState({},'',u);}catch{}searchIndex=null;const y=scrollY;render(currentHub?.path??currentPage?.path??'/overview',false);renderPrefs();scrollTo(0,y);}
let specKo=null;async function loadSpec(){try{if(LANG==='en'){specKo=specKo||specSections;const r=await fetch('/spec.en.json');if(!r.ok)throw Error();specSections=await r.json();}else if(specKo)specSections=specKo;}catch{}}
async function loadDict(){try{const r=await fetch('/i18n-en.json');if(!r.ok)throw Error();setDict(await r.json());}catch{setDict({words:{}});}}
const attrNames=['placeholder','aria-label','title','alt','aria-description','content'];
function localizeNode(root){if(LANG!=='en'||!root)return;const tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=tw.nextNode())){if(hasKo(n.nodeValue)){const v=L(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v;}}if(root.querySelectorAll)for(const el of [root,...root.querySelectorAll('*')])for(const at of attrNames){if(el.nodeType===1&&el.hasAttribute&&el.hasAttribute(at)){const o=el.getAttribute(at);if(hasKo(o)){const v=L(o);if(v!==o)el.setAttribute(at,v);}}}}
let locBusy=false;const locObs=new MutationObserver(ms=>{if(LANG!=='en'||locBusy)return;locBusy=true;try{for(const m of ms){if(m.type==='characterData'){const v=L(m.target.nodeValue);if(v!==m.target.nodeValue)m.target.nodeValue=v;}else if(m.type==='attributes'){const o=m.target.getAttribute(m.attributeName);if(o&&hasKo(o)){const v=L(o);if(v!==o)m.target.setAttribute(m.attributeName,v);}}else m.addedNodes.forEach(nd=>{nd.nodeType===3?(hasKo(nd.nodeValue)&&(nd.nodeValue=L(nd.nodeValue))):localizeNode(nd);});}if(hasKo(document.title))document.title=L(document.title);}finally{locBusy=false;}});
locObs.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:attrNames});
document.addEventListener('click',e=>{const b=e.target.closest('[data-lang],[data-theme-toggle]');if(!b)return;if(b.dataset.lang)setLang(b.dataset.lang);else setTheme(rootEl.dataset.theme==='dark'?'light':'dark');});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{try{if(localStorage.getItem('hds-theme'))return;}catch{}setTheme(e.matches?'dark':'light',false);});
if(LANG==='en'){await loadDict();await loadSpec();}
render(location.pathname==='/'?'/overview':location.pathname);renderPrefs();if(location.hash){requestAnimationFrame(()=>{const el=document.getElementById(location.hash.slice(1));el?.scrollIntoView();});}
